'use strict';

window.azAttachAnatomyMeshes=function(parts){
  const T=parts.THREE,assets=window.azRealMeshData.assets;
  function geometry(asset,transform,mirror=false){
    const binary=atob(asset.data),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
    const buf=new DataView(bytes.buffer),positions=new Float32Array(asset.n*3),indices=new Uint16Array(asset.f*3);
    for(let i=0;i<asset.n;i++){
      const xyz=[];for(let j=0;j<3;j++)xyz.push(asset.min[j]+buf.getUint16((i*3+j)*2,true)/65535*(asset.max[j]-asset.min[j]));
      const p=transform(xyz);positions.set(p,i*3);
    }
    for(let i=0;i<indices.length;i++)indices[i]=buf.getUint16(asset.n*6+i*2,true);
    // Reflections reverse triangle winding. Keep the mirrored left leg's
    // normals oriented outward like the right leg from the source model.
    if (mirror) for (let i = 0; i < indices.length; i += 3) {
      [indices[i+1], indices[i+2]] = [indices[i+2], indices[i+1]];
    }
    const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(positions,3));geo.setIndex(new T.BufferAttribute(indices,1));geo.computeVertexNormals();
    const light = atob(asset.cavityLight);
    const colors = new Uint8Array(asset.n * 3);
    for (let i = 0; i < asset.n; i++) colors.fill(light.charCodeAt(i), i * 3, i * 3 + 3);
    geo.setAttribute('color', new T.BufferAttribute(colors, 3, true));
    return geo;
  }
  function remove(parent,keep=[]){parent.children.slice().forEach(child=>{if(keep.includes(child))return;parent.remove(child);child.traverse(o=>{if(o.geometry)o.geometry.dispose();});});}
  function reliefMaterial(source) {
    const shaded = source.clone();
    // The teaching modes update this same color when a region is highlighted.
    shaded.color = source.color;
    shaded.vertexColors = true;
    return shaded;
  }
  remove(parts.head,parts.cervicalMeshes);
  const skull=assets.skull,centre=skull.min.map((v,i)=>(v+skull.max[i])/2);
  const skullGeometry=geometry(skull,p=>[(p[0]-centre[0])*.00405,(p[2]-centre[2])*.00405+.12,-(p[1]-centre[1])*.00405]);
  paintJohnnyFace(T,skullGeometry);
  const skullMaterial=new T.MeshStandardMaterial({color:0xffffff,vertexColors:true,roughness:.56,metalness:.12});
  const skullMesh=new T.Mesh(skullGeometry,skullMaterial);
  skullMesh.name='BodyParts3D skull, simplified';
  parts.head.add(skullMesh);
  const shadowMaterial=new T.MeshBasicMaterial({color:0x171821});
  function recess(name,position,scale){
    const mesh=new T.Mesh(new T.CircleGeometry(1,28),shadowMaterial);
    mesh.name=name;
    mesh.position.set(...position);
    mesh.scale.set(...scale);
    parts.head.add(mesh);
  }
  for(const side of [-1,1])recess('Johnny orbital shadow',[side*.132,.102,.185],[.091,.100,1]);
  recess('Johnny nasal shadow',[0,-.080,.179],[.068,.094,1]);
  remove(parts.pelvis);
  const pelvisMaterial = reliefMaterial(parts.materials.pelvis);
  for(const name of ['rightHip','leftHip','sacrum']){
    const mesh=new T.Mesh(geometry(assets[name],p=>[p[0]*.00582,(p[2]-840.4)*.00582,-(p[1]+79.1)*.00582+.005]),pelvisMaterial);
    mesh.name='BodyParts3D '+name;parts.pelvis.add(mesh);
  }
  // The meshes were fitted to the existing hip, knee and ankle anchors.
  // Change the visible surface only, preserving the articulation frames.
  if (assets.femur && assets.tibia && assets.patella) for (const leg of parts.legs) {
    const mirror = leg.side === 1;
    const transform = ([x, y, z]) => [mirror ? -x : x, y, z];
    const femurMaterial = reliefMaterial(leg.femurMat);
    const shinMaterial = reliefMaterial(leg.shinMat);
    const makeBone = (name, material, fit = transform) => {
      const bone = new T.Mesh(geometry(assets[name], fit, mirror), material);
      bone.name = 'BodyParts3D ' + name;
      return bone;
    };
    const femur = makeBone('femur', femurMaterial);
    const patella = makeBone('patella', femurMaterial);
    // Register the distal mortise to the talar dome in the assembled atlas
    // foot. The proximal joint fitting and the existing ankle pivot stay put.
    const tibia = makeBone('tibia', shinMaterial, position => {
      const point = transform(position);
      const depth=-point[1];
      point[1] += .126 * T.MathUtils.smoothstep(depth, .59, 1.30);
      // Leave room for the joint surfaces as the rig bends and rotates.
      point[1] -= .022 * (1-T.MathUtils.smoothstep(depth, .225, .72));
      return point;
    });
    remove(leg.femur);
    remove(leg.shin, [leg.foot, leg.fibula]);
    // The patella travels around the distal femur as the knee flexes.
    // Derive the angle from the articulated segments in the femoral frame.
    const knee = new T.Vector3(leg.side * .10, -1.63, 0);
    const pivot = new T.Group();
    pivot.name = 'Patellofemoral joint';
    pivot.position.copy(knee);
    patella.position.copy(knee).multiplyScalar(-1);
    pivot.add(patella);
    leg.femur.add(femur, pivot);
    const ankle = new T.Vector3();
    leg.fitPatella = () => {
      leg.foot.getWorldPosition(ankle);
      leg.femur.worldToLocal(ankle).sub(knee);
      const flexion = T.MathUtils.clamp(Math.atan2(-ankle.z, -ankle.y) + Math.atan2(.04, 1.31), 0, 2.75);
      pivot.rotation.x = flexion * .64;
    };
    leg.shin.add(tibia);
  }
  attachAtlasFeet(T, parts.legs, remove);
};

// Paint the red shell and gold faceplate on the skull's own surface. The
// orbit, jaw and teeth retain the atlas geometry as Johnny turns.
function paintJohnnyFace(T, geometry) {
  const {position,color}=geometry.attributes;
  const shell=new T.Color(0xbe2935), plate=new T.Color(0xf5c64c);
  const cavity=new T.Color(0x221f26), shade=new T.Color();
  const smooth=T.MathUtils.smoothstep;
  for (let i=0;i<position.count;i++) {
    const x=Math.abs(position.getX(i)), y=position.getY(i), z=position.getZ(i);
    const edge=.180+.033*smooth(y,-.19,.01)+.035*smooth(y,.02,.22);
    const browStripe=x-(.087+.048*smooth(y,.24,.53));
    const face=Math.min(edge-x,z-(.045+.15*smooth(x,.13,.28)),y+.227,Math.max(.274-y,browStripe));
    const onPlate=smooth(face,-.018,.014);
    shade.copy(shell).lerp(plate,onPlate);
    const seam=1-.24*(1-smooth(Math.abs(face),.006,.028));
    const offset=i*3;
    const relief=.72+.28*color.array[offset]/255;
    shade.multiplyScalar(seam*relief);
    const eye=(x-.137)**2/.096**2+(y-.113)**2/.083**2;
    const nose=x*x/.053**2+(y+.065)**2/.094**2;
    const recess=Math.max((1-smooth(eye,.54,1.05))*(1-smooth(z,.218,.295)),
      (1-smooth(nose,.55,1.05))*(1-smooth(z,.230,.302)))*smooth(z,.02,.115);
    shade.lerp(cavity,recess*.94);
    color.array[offset]=Math.round(shade.r*255);
    color.array[offset+1]=Math.round(shade.g*255);
    color.array[offset+2]=Math.round(shade.b*255);
  }
}

function footGeometry(T, asset, side) {
  const bytes = Uint8Array.from(atob(asset.data), character => character.charCodeAt(0));
  const data = new DataView(bytes.buffer);
  const positions = new Float32Array(asset.vertices * 3);
  for (let i = 0; i < positions.length; i++) {
    positions[i] = data.getInt16(i * 2, true) / 16000 * (i % 3 === 0 ? side : 1);
  }
  const indexOffset = positions.length * 2;
  const indices = new Uint16Array((bytes.length - indexOffset) / 2);
  for (let i = 0; i < indices.length; i++) indices[i] = data.getUint16(indexOffset + i * 2, true);
  if (side < 0) {
    for (let i = 0; i < indices.length; i += 3) [indices[i + 1], indices[i + 2]] = [indices[i + 2], indices[i + 1]];
  }
  const geometry = new T.BufferGeometry();
  geometry.setAttribute('position', new T.BufferAttribute(positions, 3));
  geometry.setIndex(new T.BufferAttribute(indices, 1));
  geometry.computeVertexNormals();
  return geometry;
}

function attachAtlasFeet(T, legs, remove) {
  for (const leg of legs) {
    const {side, foot, mid, footMat} = leg;
    remove(foot, [mid]);
    remove(mid);
    leg.footBones.length = 0;
    const local = ([x, y, z]) => new T.Vector3(side * x, y, z);

    function addBone(name, group, parentOrigin = null) {
      const asset = footSurfaces[name];
      const bone = new T.Group();
      bone.name = name;
      bone.position.copy(local(asset.center));
      if (parentOrigin) bone.position.sub(parentOrigin);
      const mesh = new T.Mesh(footGeometry(T, asset, side), footMat);
      mesh.name = 'BodyParts3D ' + name;
      bone.add(mesh);
      group.add(bone);
      leg.footBones.push(bone);
      return bone;
    }

    const calcaneus = addBone('Calcaneus', foot);
    const talus = addBone('Talus', foot);
    const navicular = addBone('Navicular', mid);
    const cuboid = addBone('Cuboid', mid);
    const cuneiforms = ['Medial', 'Intermediate', 'Lateral'].map(name => addBone(name + ' cuneiform', mid));
    const tarsals = [calcaneus, talus, navicular, cuboid, ...cuneiforms];
    const rest = tarsals.map(bone => bone.position.clone());

    const rays = toeHinges.map((hinge, index) => {
      const origin = local(hinge);
      const ray = new T.Group();
      ray.position.copy(origin);
      mid.add(ray);
      const metatarsal = new T.Group();
      ray.add(metatarsal);
      const digit = index + 1;
      addBone('Metatarsal ' + digit, metatarsal, origin);
      const toes = new T.Group();
      ray.add(toes);
      for (const part of digit === 1 ? ['Proximal', 'Distal'] : ['Proximal', 'Middle', 'Distal']) {
        addBone(part + ' phalanx ' + digit, toes, origin);
      }
      if (digit === 1) {
        addBone('Medial sesamoid', ray, origin);
        addBone('Lateral sesamoid', ray, origin);
      }
      return {ray, metatarsal, toes, origin};
    });

    leg.navicular = navicular;
    leg.rays = rays.map(({ray}) => ray);
    leg.footLandmarks = {calcaneus, talus, navicular, head: rays[0].ray};
    leg.poseFootArch = amount => {
      tarsals.forEach((bone, index) => bone.position.copy(rest[index]));
      // Loaded example: heel everts, talar head moves medially, and the
      // medial column lowers more than the lateral column. Bones stay rigid.
      calcaneus.rotation.z = side * amount * .065;
      talus.position.x -= side * amount * .010;
      talus.position.y -= amount * .012;
      talus.rotation.y = -side * amount * .048;
      navicular.position.y -= amount * .034;
      navicular.position.z += amount * .004;
      navicular.rotation.y = side * amount * .036;
      navicular.rotation.x = -amount * .036;
      cuboid.position.y -= amount * .004;
      for (const [index, bone] of cuneiforms.entries()) {
        bone.position.y -= amount * (.031 - index * .008);
        bone.position.z += amount * .006;
        bone.rotation.x = -amount * (.044 - index * .008);
      }
      for (const [index, {ray, metatarsal, origin}] of rays.entries()) {
        const medial = 1 - index * .18;
        ray.position.copy(origin);
        ray.position.x += side * amount * (index - 2) * .002;
        ray.rotation.y = side * amount * (.032 + index * .006);
        metatarsal.rotation.x = -amount * .15 * medial;
      }
    };
    leg.poseToes = angle => {
      for (const {toes} of rays) toes.rotation.x = -angle;
    };
  }
}
